import React from 'react';

import { formatAltitude } from '@helpers/formatHelper';
import { getDistanceBetweenPointsInMeters, getDistanceByCoordsInMeters } from '@helpers/gpsHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';

import { formatDistance } from '../../../@classes/XneekPolylineEditor/helpers';

interface ISummaryProps {
  points: Array<[number, number, number]>;
}

const Summary: React.FC<ISummaryProps> = ({ points }) => {
  const [data, setData] = React.useState<Record<string, number | string | string[]>>({});
  React.useEffect(() => {
    if (points.length < 2) {
      return;
    }

    if (!points[0]?.[2]) return;

    let altMin = Infinity;
    let altMax = -Infinity;

    let altSum = 0;
    let totalDesc = 0;
    let totalAsc = 0;

    let distDesc = 0;
    let distAsc = 0;
    let dist0 = 0;

    points.forEach((p, i, all) => {
      const alt = p[2] || all[i - 1][2];

      if (alt < altMin) altMin = alt;
      if (alt > altMax) altMax = alt;
      altSum += alt;

      if (i > 0) {
        const prevAlt = all[i - 1][2];
        if (Math.round(alt) === Math.round(prevAlt)) {
          dist0 += getDistanceBetweenPointsInMeters(all[i - 1], all[i]);
        } else if (alt > prevAlt) {
          totalAsc += alt - prevAlt;
          distAsc += getDistanceBetweenPointsInMeters(all[i - 1], all[i]);
        } else {
          totalDesc += prevAlt - alt;
          distDesc += getDistanceBetweenPointsInMeters(all[i - 1], all[i]);
        }
      }
    });

    const dist = getDistanceByCoordsInMeters(points);

    setData({
      distance: formatDistance(dist),
      distanceAsc: formatDistance(distAsc),
      distanceAscPct: Math.round((distAsc / dist) * 100),
      distanceDesc: formatDistance(distDesc),
      distanceDescPct: Math.round((distDesc / dist) * 100),
      distance0: formatDistance(dist0),
      distance0Pct: Math.round((dist0 / dist) * 100),
      minAlt: formatAltitude(altMin),
      maxAlt: formatAltitude(altMax),
      rangeAlt: formatAltitude(altMax - altMin),
      avgAlt: formatAltitude(altSum / points.length),
      totalDesc,
      totalAsc,
    });
    //pointsCount: points.length,
  }, [points]);

  return (
    <div className="p-2">
      <div className="d-flex flex-column" style={{ gap: 4 }}>
        <div className="d-flex flex-column" style={{ gap: 2 }}>
          <PohBadge variant={BadgeVariant.Success}>
            <small className="me-auto">Дист:</small>
            <strong>{data.distance}</strong>
          </PohBadge>

          <PohBadge title={data.distance0Pct + '%'}>
            <small className="me-auto">Плоск.: </small>
            <small>{data.distance0}</small>
          </PohBadge>
          <PohBadge title={data.distanceAscPct + '%'}>
            <small className="me-auto">Набор: </small>
            <small>{data.distanceAsc}</small>
          </PohBadge>
          <PohBadge title={data.distanceDescPct + '%'}>
            <small className="me-auto">Сброс: </small>
            <small>{data.distanceDesc}</small>
          </PohBadge>
        </div>

        <div className="d-flex flex-column" style={{ gap: 2 }}>
          <small>
            <small className="text-success">Высота</small>
          </small>
          <PohBadge variant={BadgeVariant.Success}>
            <small className="me-auto">Набор: </small>
            <strong>{formatAltitude(+data.totalAsc)}</strong>
          </PohBadge>
          <PohBadge variant={BadgeVariant.Success}>
            <small className="me-auto">Сброс: </small>
            <strong>{formatAltitude(+data.totalDesc)}</strong>
          </PohBadge>

          <PohBadge>
            <small className="me-auto">Макс: </small>
            <small>{data.maxAlt}</small>
          </PohBadge>
          <PohBadge>
            <small className="me-auto">Мин: </small>
            <small>{data.minAlt}</small>
          </PohBadge>
          <PohBadge>
            <small className="me-auto">Средн: </small>
            <small>{data.avgAlt}</small>
          </PohBadge>
          <PohBadge>
            <small className="me-auto">Перепад: </small>
            <small>{data.rangeAlt}</small>
          </PohBadge>
        </div>
      </div>
    </div>
  );
};

export default Summary;
